package study
import"testing"
func TestScoreRequiresPinnedBalancedPassingPairs(t *testing.T){task:=Task{ID:"t",Model:"m",Tools:[]string{"tool"},Limit:10,Oracle:"o"};m:=Manifest{SchemaVersion:"1.0.0",StudyID:"s",MinimumPairs:1,Tasks:[]Task{task}};out:=func(arm,status string)Outcome{return Outcome{TaskID:"t",Arm:arm,Model:"m",Tools:[]string{"tool"},Limit:10,Oracle:"o",Status:status}};report,err:=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{out("control","PASS"),out("workflow","PASS")}});if err!=nil||!report.ClaimAllowed{t.Fatal(err)};report,_=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{out("control","PASS"),out("workflow","TIMEOUT")}});if report.ClaimAllowed{t.Fatal("timeout must block claim")}}
func TestScoreRejectsUnpinnedOutcome(t *testing.T){m:=Manifest{SchemaVersion:"1.0.0",StudyID:"s",MinimumPairs:1,Tasks:[]Task{{ID:"t",Model:"m",Tools:[]string{"x"},Limit:1,Oracle:"o"}}};_,err:=Score(m,Results{SchemaVersion:"1.0.0",StudyID:"s",Outcomes:[]Outcome{{TaskID:"t",Arm:"control",Model:"other",Tools:[]string{"x"},Limit:1,Oracle:"o",Status:"PASS"}}});if err==nil{t.Fatal("expected pin mismatch")}}